<script lang="ts">
import{onMount}from'svelte';import{api}from'../../lib/api';
type Borrower={id:number;name:string};type Loan={id:number;copy_id:number;book_id:number;book_title:string;borrower_id:number;borrower:string;checked_out_at:string;due_date:string|null;copy_label:string;shelf:string};type Page={loans:Loan[];total:number;page:number;page_size:number;today:string};
let result:Page|null=null;let borrowers:Borrower[]=[];let borrower='';let due='';let page=1;let error='';let message='';let busy=false;let loading=true;let sequence=0;const keys=new Map<number,string>();
async function load(){const current=++sequence;error='';try{const params=new URLSearchParams({page:String(page)});if(borrower)params.set('borrower_id',borrower);if(due)params.set('due',due);const next=await api<Page>(`/api/loans?${params}`);if(current===sequence)result=next;}catch(e){if(current===sequence)error=(e as Error).message;}finally{if(current===sequence)loading=false;}}
onMount(()=>{load();api<Borrower[]>('/api/borrowers').then(v=>borrowers=v).catch(e=>error=e.message);const refresh=()=>load();window.addEventListener('focus',refresh);return()=>window.removeEventListener('focus',refresh);});
function filter(){page=1;load();}
async function returnLoan(id:number){busy=true;error='';if(!keys.has(id))keys.set(id,crypto.randomUUID());try{await api(`/api/loans/${id}/return`,{request_key:keys.get(id)});keys.delete(id);await load();if(result&&result.loans.length===0&&page>1){page--;await load();}message='Book returned.';window.dispatchEvent(new Event('library-inventory-changed'));}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="loans_wrap">{#if error}<p role="alert" class="library-error">{error}</p>{/if}<form class="loans_filters" onsubmit={(e)=>{e.preventDefault();filter();}}><label class="library-field">Borrower<select bind:value={borrower} onchange={filter}><option value="">Everyone</option>{#each borrowers as b}<option value={b.id}>{b.name}</option>{/each}</select></label><label class="library-field">Due date<select bind:value={due} onchange={filter}><option value="">All outstanding loans</option><option value="overdue">Overdue</option><option value="upcoming">Due today or later</option></select></label></form>{#if loading}<p>Loading loans…</p>{:else if result}<p>{result.total} outstanding {result.total===1?'loan':'loans'}{#if borrower||due} matching your filters{/if}.</p><p class="library-help">Due dates compare against {result.today} (UTC). Copies remain assigned to their home shelf while on loan.</p>{#each result.loans as loan}<article class="loan_row"><div><h2><a href={`/books/${loan.book_id}/`}>{loan.book_title}</a></h2><p>{loan.copy_label||`Copy ${loan.copy_id}`} · {loan.shelf}</p><p>Lent to <strong>{loan.borrower}</strong> · Checked out {loan.checked_out_at.slice(0,10)}</p>{#if loan.due_date}<p class:overdue={loan.due_date<result.today}>Due {loan.due_date}{loan.due_date<result.today?' · Overdue':''}</p>{:else}<p>No due date</p>{/if}</div><button class="library-button" disabled={busy} onclick={()=>returnLoan(loan.id)}>Return book</button></article>{/each}{#if !result.loans.length}<p>No outstanding loans match these filters.</p>{/if}{#if result.total>result.page_size}<div class="library-actions"><button class="library-button secondary" disabled={page===1||busy} onclick={()=>{page--;load();}}>Previous</button><span>Page {page} of {Math.ceil(result.total/result.page_size)}</span><button class="library-button secondary" disabled={page*result.page_size>=result.total||busy} onclick={()=>{page++;load();}}>Next</button></div>{/if}{/if}<p role="status">{message}</p></div>
<style>@layer components{.loans_wrap{display:grid;gap:var(--space-4)}.loans_filters{display:flex;flex-wrap:wrap;gap:var(--space-3);label{flex:1;min-width:12rem}}.loan_row{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--space-3);border:var(--border-width) solid var(--border);border-radius:var(--radius-main);padding:var(--space-4);background:var(--background-3);h2{font-size:var(--h5)}}.overdue{color:var(--text-1);font-weight:700}} </style>
